<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { Activity, CalendarCheck, Clock3, Dumbbell } from 'lucide-vue-next'
import AppChart from '@/components/ui/AppChart.vue'
import AppCard from '@/components/ui/AppCard.vue'
import AppEmptyState from '@/components/ui/AppEmptyState.vue'
import AppInput from '@/components/ui/AppInput.vue'
import AppPageHeader from '@/components/ui/AppPageHeader.vue'
import AppSelect from '@/components/ui/AppSelect.vue'
import AppSegmentedControl from '@/components/ui/AppSegmentedControl.vue'
import { cardioLogRepository } from '@/repositories/cardioLogRepository'
import { exerciseRepository } from '@/repositories/exerciseRepository'
import { weightLogRepository } from '@/repositories/weightLogRepository'
import { calculateCardioStats, calculateGeneralStats, calculateMuscleGroupStats, calculateWeightStats, cardioProgressPoints, weeklyTrainingPoints, weightProgressPoints } from '@/services/statistics'
import { useSummaryFiltersStore } from '@/stores/summaryFilters'
import { formatItalianDate, toDateKey } from '@/utils/date'
import { formatNumber } from '@/utils/number'
import type { CardioLog, Exercise, WeightLogWithSets } from '@/models'

const filters=useSummaryFiltersStore(),{period,from,to,type,exerciseId}=storeToRefs(filters)
const allWeights=ref<WeightLogWithSets[]>([]),allCardio=ref<CardioLog[]>([]),exercises=ref<Exercise[]>([]),loading=ref(true)
function shiftDays(key:string,amount:number){const d=new Date(`${key}T12:00:00`);d.setDate(d.getDate()+amount);return toDateKey(d)}
function applyPeriod(){if(period.value==='custom')return;to.value=toDateKey();from.value=shiftDays(to.value,-(Number(period.value)-1))}
watch(period,applyPeriod,{immediate:true})
const exerciseOptions=computed(()=>[{value:'',label:'Tutti gli esercizi'},...exercises.value.filter(e=>type.value==='all'||e.type===type.value).map(e=>({value:e.id,label:e.name}))])
watch(type,()=>{if(exerciseId.value&&!exerciseOptions.value.some(x=>x.value===exerciseId.value))exerciseId.value=''})
const weights=computed(()=>type.value==='cardio'?[]:allWeights.value.filter(l=>l.date>=from.value&&l.date<=to.value&&(!exerciseId.value||l.exerciseId===exerciseId.value)))
const cardio=computed(()=>type.value==='weights'?[]:allCardio.value.filter(l=>l.date>=from.value&&l.date<=to.value&&(!exerciseId.value||l.exerciseId===exerciseId.value)))
const general=computed(()=>{const stats=calculateGeneralStats(weights.value,cardio.value,from.value,to.value);return{...stats,cardioMinutes:formatNumber(stats.cardioMinutes)}}),weightStats=computed(()=>calculateWeightStats(weights.value)),cardioStats=computed(()=>calculateCardioStats(cardio.value).map(stats=>({...stats,totalMinutes:formatNumber(stats.totalMinutes),maxMinutes:formatNumber(stats.maxMinutes)}))),weekly=computed(()=>weeklyTrainingPoints(weights.value,cardio.value))
const muscleGroupSummary=computed(()=>calculateMuscleGroupStats(weights.value,exercises.value))
const mostFrequentMuscleGroup=computed(()=>{const group=muscleGroupSummary.value.mostFrequent;return group?group.charAt(0).toLocaleUpperCase('it-IT')+group.slice(1):'—'})
const muscleGroupPoints=computed(()=>muscleGroupSummary.value.groups.map(stats=>({label:stats.group.charAt(0).toLocaleUpperCase('it-IT')+stats.group.slice(1),value:stats.totalSets})))
const displayedWeightProgressPoints=(exerciseId:string,mode:'total'|'per_side')=>weightProgressPoints(weights.value,exerciseId,mode).filter(point=>point.value!==0)
const hasData=computed(()=>weights.value.length||cardio.value.length)
onMounted(async()=>{[allWeights.value,allCardio.value,exercises.value]=await Promise.all([weightLogRepository.listBetween(),cardioLogRepository.listBetween(),exerciseRepository.list()]);loading.value=false})
</script>
<template><div class="page"><AppPageHeader title="Riepilogo" subtitle="Statistiche e progressi"/><AppCard><div class="filters"><AppSegmentedControl v-model="period" label="Periodo" :options="[{value:'7',label:'7 giorni'},{value:'30',label:'30 giorni'},{value:'90',label:'90 giorni'},{value:'custom',label:'Personal.'}]"/><div v-if="period==='custom'" class="date-grid"><AppInput v-model="from" label="Dal" type="date"/><AppInput v-model="to" label="Al" type="date"/></div><AppSegmentedControl v-model="type" label="Contenuto" :options="[{value:'all',label:'Tutti'},{value:'weights',label:'Pesi'},{value:'cardio',label:'Cardio'}]"/><AppSelect v-model="exerciseId" label="Esercizio" :options="exerciseOptions"/></div></AppCard><p v-if="loading" class="muted">Calcolo statistiche…</p><AppEmptyState v-else-if="!hasData" title="Nessun dato nel periodo" description="Prova ad ampliare l’intervallo o a cambiare i filtri."/><template v-else><section class="stat-grid" aria-label="Statistiche generali"><div class="stat-row stat-row--two"><AppCard><CalendarCheck :size="22"/><span>Giorni allenati</span><strong>{{general.trainingDays}}</strong></AppCard><AppCard><span>Media settimanale</span><strong>{{formatNumber(general.weeklyFrequency)}}</strong><small>giorni/settimana</small></AppCard></div><div class="stat-row stat-row--three"><AppCard><Dumbbell :size="22"/><span>Registrazioni pesi</span><strong>{{general.weightLogs}}</strong></AppCard><AppCard><Activity :size="22"/><span>Serie totali</span><strong>{{general.totalSets}}</strong></AppCard><AppCard><Clock3 :size="22"/><span>Minuti cardio</span><strong>{{general.cardioMinutes}}</strong></AppCard></div><div class="stat-row stat-row--three"><AppCard><span>Pesi più frequente</span><strong class="text-value">{{general.mostFrequentWeight??'—'}}</strong></AppCard><AppCard><span>Gruppo muscolare più frequente</span><strong class="text-value">{{mostFrequentMuscleGroup}}</strong></AppCard><AppCard><span>Cardio più frequente</span><strong class="text-value">{{general.mostFrequentCardio??'—'}}</strong></AppCard></div></section><AppCard v-if="weekly.length"><AppChart title="Giornate di allenamento per settimana" :points="weekly" suffix=" gg"/></AppCard><section v-if="weights.length" class="detail-section"><h2>Gruppi muscolari</h2><AppCard><template v-if="muscleGroupSummary.groups.length"><AppChart title="Serie per gruppo muscolare" :points="muscleGroupPoints" suffix=" serie"/><div class="mode-grid"><div v-for="stats in muscleGroupSummary.groups" :key="stats.group" class="mode-stat"><strong>{{stats.group.charAt(0).toLocaleUpperCase('it-IT')+stats.group.slice(1)}}</strong><span>Sessioni: {{stats.sessions}}</span><span>Serie: {{stats.totalSets}}</span><span>Esercizi: {{stats.exerciseCount}}</span></div></div></template><p v-else class="muted">Nessuna statistica disponibile: assegna il gruppo muscolare agli esercizi da Altro → Esercizi.</p><p v-if="muscleGroupSummary.unassignedLogs" class="muted">Registrazioni senza gruppo: {{muscleGroupSummary.unassignedLogs}} · serie non conteggiate: {{muscleGroupSummary.unassignedSets}}.</p></AppCard></section><section v-if="weightStats.length" class="detail-section"><h2>Riepilogo pesi</h2><AppCard v-for="exercise in weightStats" :key="exercise.exerciseId"><div class="detail-title"><h3>{{exercise.name}}</h3><span>{{exercise.sessions}} sessioni · {{exercise.totalSets}} serie</span></div><p class="muted">Ultima esecuzione: {{formatItalianDate(exercise.lastDate,{day:'2-digit',month:'2-digit',year:'numeric'})}}</p><div class="mode-grid"><div v-for="mode in exercise.modes" :key="mode.mode" class="mode-stat"><strong>{{mode.maxWeight!==0?(mode.mode==='total'?'Totale':'Per parte'):'Ripetizioni'}}</strong><span v-if="mode.latestWeight!==0">Ultimo peso {{formatNumber(mode.latestWeight)}} kg</span><span v-if="mode.maxWeight!==0">Massimo {{formatNumber(mode.maxWeight)}} kg</span><span>Massimo {{mode.maxRepetitions}} rep</span></div></div><div class="charts"><template v-for="mode in exercise.modes" :key="mode.mode"><AppChart v-if="mode.maxWeight!==0" :title="`Peso massimo · ${mode.mode==='total'?'totale':'per parte'}`" :points="displayedWeightProgressPoints(exercise.exerciseId,mode.mode)" kind="line" suffix=" kg"/></template></div></AppCard></section><section v-if="cardioStats.length" class="detail-section"><h2>Riepilogo cardio</h2><AppCard v-for="exercise in cardioStats" :key="exercise.exerciseId"><div class="detail-title"><h3>{{exercise.name}}</h3><span>{{exercise.sessions}} sessioni</span></div><div class="mode-grid"><div class="mode-stat"><span>Totale {{exercise.totalMinutes}} min</span><span>Media {{formatNumber(exercise.averageMinutes)}} min</span><span>Massimo {{exercise.maxMinutes}} min</span><span>Ultima {{formatItalianDate(exercise.lastDate,{day:'2-digit',month:'2-digit',year:'numeric'})}}</span></div></div><AppChart title="Minuti cardio nel tempo" :points="cardioProgressPoints(cardio,exercise.exerciseId)" kind="line" suffix=" min"/></AppCard></section></template></div></template>
<style scoped>.filters,.detail-section{display:grid;gap:var(--space-3)}.date-grid{display:grid;grid-template-columns:1fr 1fr;gap:var(--space-3)}.stat-grid,.stat-row{display:grid;gap:var(--space-3)}.stat-row--two{grid-template-columns:repeat(2,minmax(0,1fr))}.stat-row--three{grid-template-columns:repeat(3,minmax(0,1fr))}.stat-row>.card{display:grid;align-content:start;gap:var(--space-2);min-width:0}.stat-grid svg{color:var(--color-accent-text)}.stat-grid span,.stat-grid small{color:var(--color-text-muted);font-size:var(--text-sm);overflow-wrap:anywhere}.stat-grid strong{font-size:var(--text-xl);font-variant-numeric:tabular-nums;overflow-wrap:anywhere}.stat-grid .text-value{font-size:var(--text-md)}.detail-section>h2{margin:var(--space-3) 0 var(--space-1);font-size:var(--text-lg)}.detail-section>.card{display:grid;gap:var(--space-4)}.detail-title{display:flex;justify-content:space-between;gap:var(--space-3)}.detail-title h3{margin:0}.detail-title span{color:var(--color-text-muted);font-size:var(--text-sm);text-align:right}.detail-section p{margin:0}.mode-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:var(--space-2)}.mode-stat{display:grid;gap:var(--space-1);padding:var(--space-3);border-radius:var(--radius-sm);background:var(--color-surface-subtle);font-size:var(--text-sm)}.charts{display:grid;gap:var(--space-5)}</style>
